insert into daraja.questions(venue, level, kind, theme, question, options, answer_idx, explanation, payload) values
-- VRAI OU FAUX (options fixes : 0 = Vrai, 1 = Faux)
(null,1,'tf','Vrai ou faux','Le Negroni est né à Florence : un comte a demandé un Americano plus fort, avec du gin à la place de l''eau gazeuse.','["Vrai","Faux"]',0,'Vrai ! Le comte Camillo Negroni, vers 1919, au Caffè Casoni de Florence.',null),
(null,1,'tf','Vrai ou faux','Le Moscow Mule a été inventé à Moscou.','["Vrai","Faux"]',1,'Faux ! Il est né aux États-Unis vers 1941, pour aider à vendre de la vodka et du ginger beer.',null),
(null,1,'tf','Vrai ou faux','On peut faire de la tequila avec n''importe quel agave.','["Vrai","Faux"]',1,'Faux ! Uniquement l''agave bleu (Weber). Le mezcal, lui, peut utiliser plusieurs espèces d''agave.',null),
(null,1,'tf','Vrai ou faux','Le goût principal du gin vient des baies de genièvre.','["Vrai","Faux"]',0,'Vrai ! Sans genièvre, ce n''est pas du gin. Le reste (agrumes, épices, herbes) fait la signature de chaque marque.',null),
(null,1,'tf','Vrai ou faux','On peut produire du champagne partout en France.','["Vrai","Faux"]',1,'Faux ! Seulement dans la région Champagne. Ailleurs, on parle de crémant ou de vin mousseux.',null),
(null,1,'tf','Vrai ou faux','Le rhum est fabriqué à partir de la canne à sucre.','["Vrai","Faux"]',0,'Vrai ! À partir de mélasse ou de pur jus de canne (rhum agricole).',null),
(null,1,'tf','Vrai ou faux','La vodka doit obligatoirement être faite à partir de pommes de terre.','["Vrai","Faux"]',1,'Faux ! Céréales, pommes de terre, raisin… Grey Goose est par exemple faite à partir de blé français.',null),
(null,2,'tf','Vrai ou faux','L''Espresso Martini a été créé à Londres dans les années 1980.','["Vrai","Faux"]',0,'Vrai ! Par le bartender Dick Bradsell, pour une cliente qui voulait un verre pour la réveiller.',null),
(null,2,'tf','Vrai ou faux','On sait exactement qui a inventé la Margarita.','["Vrai","Faux"]',1,'Faux ! Plusieurs bars et bartenders revendiquent sa création. Le mystère fait partie de la légende.',null),
(null,2,'tf','Vrai ou faux','Un bourbon doit obligatoirement être fabriqué au Kentucky.','["Vrai","Faux"]',1,'Faux ! Il doit être fait aux États-Unis. Le Kentucky en produit la grande majorité, mais pas l''exclusivité.',null),
(null,2,'tf','Vrai ou faux','Un Scotch whisky doit vieillir au moins 3 ans en fût de chêne.','["Vrai","Faux"]',0,'Vrai ! C''est la règle minimum en Écosse.',null),
(null,2,'tf','Vrai ou faux','Le ver dans la bouteille fait partie de la tradition de tous les mezcals.','["Vrai","Faux"]',1,'Faux ! C''était surtout un coup marketing. Les grands mezcals n''en ont pas.',null),
(null,2,'tf','Vrai ou faux','Les bartenders recommandent de secouer un Dry Martini, comme James Bond.','["Vrai","Faux"]',1,'Faux ! Un cocktail sans jus se remue : il reste limpide et soyeux. Bond, lui, le voulait secoué.',null),
(null,2,'tf','Vrai ou faux','La recette classique de l''Apérol Spritz est 3 doses de prosecco, 2 d''Apérol, 1 d''eau gazeuse.','["Vrai","Faux"]',0,'Vrai ! Le fameux 3-2-1.',null),
(null,2,'tf','Vrai ou faux','Le Pisco est revendiqué à la fois par le Pérou et par le Chili.','["Vrai","Faux"]',0,'Vrai ! Les deux pays se disputent son origine depuis des siècles.',null),
(null,2,'tf','Vrai ou faux','On peut offrir un shot à un client en échange d''un avis Google.','["Vrai","Faux"]',1,'Faux ! Google interdit les avis contre un avantage. On demande, on ne paie jamais un avis.',null),
(null,3,'tf','Vrai ou faux','À l''origine, la couleur rouge du Campari venait d''un insecte, la cochenille.','["Vrai","Faux"]',0,'Vrai ! Le colorant carmin a été remplacé depuis par un colorant artificiel.',null),
(null,3,'tf','Vrai ou faux','Le Penicillin est un cocktail créé au XIXe siècle par un médecin.','["Vrai","Faux"]',1,'Faux ! Il a été créé en 2005 à New York par le bartender Sam Ross, au bar Milk & Honey.',null),
(null,3,'tf','Vrai ou faux','La Piña Colada est la boisson nationale de Porto Rico.','["Vrai","Faux"]',0,'Vrai ! Officiellement depuis 1978.',null),
(null,3,'tf','Vrai ou faux','Le Cognac est une eau-de-vie de raisin.','["Vrai","Faux"]',0,'Vrai ! Distillé deux fois puis vieilli en fût de chêne, dans la région de Cognac.',null),
-- ORIGINES DES SPIRITUEUX (QCM)
(null,1,'qcm','Spiritueux','D''où vient la tequila ?','["Du Mexique","De l''Espagne","Du Brésil","De Cuba"]',0,'Principalement de l''État de Jalisco, au Mexique.',null),
(null,1,'qcm','Spiritueux','Le Limoncello est une liqueur de…','["Citron, du sud de l''Italie","Orange, d''Espagne","Menthe, du Maroc","Fraise, de France"]',0,'Côte amalfitaine et Sorrente : des zestes de citron macérés dans l''alcool.',null),
(null,2,'qcm','Spiritueux','Le gin descend d''un alcool hollandais appelé…','["Le genever","Le schnaps","L''aquavit","Le kirsch"]',0,'Les soldats anglais l''ont découvert aux Pays-Bas et l''ont ramené à Londres.',null),
(null,2,'qcm','Spiritueux','Le mezcal San Cosme de la carte vient de quel État mexicain réputé pour le mezcal ?','["Oaxaca","Jalisco","Yucatán","Sonora"]',0,'Oaxaca est la capitale du mezcal, souvent au goût fumé.',null),
(null,2,'qcm','Spiritueux','Pourquoi le mezcal a-t-il souvent un goût fumé ?','["Le cœur d''agave est cuit dans des fours en terre","On y ajoute de la fumée liquide","Il vieillit dans des fûts brûlés","À cause du ver"]',0,'Les cœurs d''agave (piñas) sont cuits lentement dans des fosses chauffées au bois.',null),
(null,3,'qcm','Spiritueux','Le Zacapa 23 de la carte est un rhum de quel pays ?','["Guatemala","Cuba","Jamaïque","Martinique"]',0,'Un rhum vieilli en altitude, réputé pour sa rondeur.',null),
-- SCÈNES CLIENT (affichées comme une conversation)
(null,1,'scene','Avis Google','Le client : « C''était parfait, merci ! On reviendra. »','["Ça nous touche ! Si vous avez une minute, un avis sur Google aide beaucoup notre équipe.","Laissez-nous 5 étoiles svp !","Ok merci, bonne soirée.","Vous devez mettre un avis avant de partir."]',0,'Le bon moment, c''est quand le client exprime lui-même sa satisfaction. On demande, sans forcer.',null),
(null,2,'scene','Avis Google','Le client a attendu son plat 40 minutes et soupire en payant.','["On s''excuse sincèrement, on prévient le manager, et on ne demande pas d''avis ce soir","On lui demande un avis Google quand même","On ne dit rien","On lui explique que la cuisine était débordée et que ce n''est pas notre faute"]',0,'On répare d''abord. Un client mécontent bien rattrapé peut devenir ton meilleur ambassadeur.',null),
(null,2,'scene','Avis Google','Le client : « Comment je vous trouve sur Google ? »','["Je vous montre : le plus simple, c''est ce QR code, ça prend 30 secondes","Cherchez sur internet","Je ne sais pas","Sur Facebook plutôt"]',0,'Toujours avoir le lien ou le QR code sous la main : on rend le geste facile.',null),
(null,3,'scene','Avis Google','Le client veut citer ton prénom dans son avis. Tu dis…','["Avec plaisir ! Merci, ça me touche beaucoup, et toute l''équipe sera ravie.","Non, ce n''est pas la peine","Mettez plutôt le nom du manager","Écrivez que le service était parfait"]',0,'Un avis qui cite ton prénom te rapporte +100 pts une fois validé. Et ça fait plaisir à toute l''équipe.',null),
(null,1,'scene','Gentillesse','Le client : « C''est notre anniversaire de mariage ce soir. »','["Félicitations ! Je vais faire en sorte que ce soit une soirée inoubliable.","Ah d''accord.","Vous voulez l''addition ?","Ça fait combien d''années ?"]',0,'Un moment spécial à repérer : on prévient le manager pour une attention (bougie, dessert, mot).',null),
(null,1,'scene','Gentillesse','Le client : « Surprenez-moi ! »','["Avec plaisir ! Plutôt frais et fruité, ou intense et épicé ?","Je vous mets le plus cher","Je ne sais pas, regardez la carte","Un mojito alors"]',0,'Une question de goût suffit pour viser juste. Et le client se sent écouté.',null),
(null,2,'scene','Gentillesse','Un touriste demande : « What is ras el hanout? »','["It''s a Moroccan spice blend, warm and fragrant. It literally means head of the shop.","It''s a cheese","I don''t know","It''s very spicy, don''t take it"]',0,'Ras el hanout signifie « la tête de la boutique » : le meilleur mélange de l''épicier.',null),
(null,2,'scene','Gentillesse','Le client hésite devant le prix du Pommard.','["Je vous propose aussi le Bourgogne Pinot Noir, même cépage, très élégant et plus accessible","Il n''y a rien de moins cher","Le prix est indiqué sur la carte","Prenez-le, vous ne le regretterez pas"]',0,'On guide sans gêner : une alternative dans le même style, sans jamais juger le budget.',null),
(null,3,'scene','Gentillesse','Le client : « C''est épicé, le Naughty Tequila ? »','["Oui, c''est intense : piment, poivrons et harissa. Si vous aimez le feu, foncez, sinon je vous conseille le Liquid Sunshine","Non pas du tout","Un peu","Je ne sais pas, je ne l''ai jamais goûté"]',0,'L''honnêteté avant tout : un client prévenu est un client content.',null),
-- ANGLAIS (QCM)
(null,1,'qcm','English','« Prenez votre temps » en anglais :','["Take your time","Take the time","Have your time","Make your time"]',0,'« Take your time, I''ll come back in a minute. »',null),
(null,1,'qcm','English','« L''addition, s''il vous plaît » : le client anglais dit…','["The bill, please","The addition, please","The note, please","The count, please"]',0,'« Bill » en Angleterre, « check » aux États-Unis.',null),
(null,1,'qcm','English','Comment dire « Bon appétit » à un client anglophone ?','["Enjoy your meal","Good appetite","Eat well","Have a good food"]',0,'« Enjoy your meal » est la formule naturelle.',null),
(null,1,'qcm','English','« Je reviens tout de suite » se dit…','["I''ll be right back","I come back now","I return quickly","I''m coming back soon"]',0,'Court, poli, naturel.',null),
(null,2,'qcm','English','« Effiloché de bœuf » en anglais :','["Pulled beef","Shredded cow","Pulled cow","Torn beef"]',0,'« Pulled » : comme le célèbre pulled pork.',null),
(null,2,'qcm','English','« Loup bar » en anglais :','["Sea bass","Sea wolf","Bar fish","Sea bream"]',0,'Sea bass. La daurade, elle, se dit sea bream.',null),
(null,2,'qcm','English','« Citron confit » en anglais :','["Preserved lemon","Candied lemon","Confit lemon","Pickled orange"]',0,'Preserved lemon : un classique de la cuisine marocaine.',null),
(null,2,'qcm','English','Quelle phrase est correcte ?','["I agree with you","I am agree with you","I''m agree","I agreed with you now"]',0,'Erreur très fréquente : on ne dit jamais « I am agree ».',null),
(null,3,'qcm','English','Le client demande « Is the octopus grilled? ». Il parle du…','["Poulpe","Calamar","Gambas","Poisson du jour"]',0,'Octopus = poulpe, squid = calamar, prawns = gambas.',null),
(null,3,'qcm','English','« Cèpes » en anglais :','["Porcini mushrooms","Button mushrooms","Truffles","Morels"]',0,'Le nom italien porcini est utilisé en anglais.',null),
