(null,2,'match','Associations','Relie chaque formule polie à sa traduction','[]',0,'La politesse, la base.','{"pairs":[["Prenez votre temps","Take your time"],["Je reviens tout de suite","I''ll be right back"],["Santé !","Cheers!"],["Bon appétit","Enjoy your meal"]]}'),
