('encouragement','Ce soir, tu ne sers pas des plats. Tu crées des souvenirs.',null),
('encouragement','Aide un collègue aujourd''hui. Il s''en souviendra.',null);

with p as (
  select q.id, q.options->>q.answer_idx as correct,
    (select jsonb_agg(e order by random()) from jsonb_array_elements(q.options) e) as shuffled
  from daraja.questions q where q.kind in ('qcm','scene','price') and q.answer_idx = 0 and jsonb_array_length(q.options) > 1
)
update daraja.questions q set options = p.shuffled,
  answer_idx = (select (ord - 1)::int from jsonb_array_elements_text(p.shuffled) with ordinality t(v, ord) where v = p.correct limit 1)
from p where p.id = q.id;
select kind, count(*) from daraja.questions group by 1 order by 1;
